#[ORM\Table(name: 'user_roles')]
class UserRole
{
    // Составной PK из двух полей
    #[ORM\Id]
    #[ORM\Column(type: 'integer')]
    private int $userId;

    #[ORM\Id]
    #[ORM\Column(type: 'string', length: 50)]
    private string $role;

    public function __construct(int $userId, string $role)
    {
        $this->userId = $userId;
        $this->role = $role;
    }
}

